248|int mbedtls_asn1_traverse_sequence_of(
249|    unsigned char **p,
250|    const unsigned char *end,
251|    unsigned char tag_must_mask, unsigned char tag_must_val,
252|    unsigned char tag_may_mask, unsigned char tag_may_val,
253|    int (*cb)( void *ctx, int tag,
254|               unsigned char *start, size_t len ),
255|    void *ctx )
256|{
257|    int ret;
258|    size_t len;
259|
260|    /* Get main sequence tag */
261|    if( ( ret = mbedtls_asn1_get_tag( p, end, &len,
262|            MBEDTLS_ASN1_CONSTRUCTED | MBEDTLS_ASN1_SEQUENCE ) ) != 0 )
263|    {
264|        return( ret );
265|    }
266|
267|    if( *p + len != end )
268|        return( MBEDTLS_ERR_ASN1_LENGTH_MISMATCH );
269|
270|    while( *p < end )
271|    {
272|        unsigned char const tag = *(*p)++;
273|
274|        if( ( tag & tag_must_mask ) != tag_must_val )
275|            return( MBEDTLS_ERR_ASN1_UNEXPECTED_TAG );
276|
277|        if( ( ret = mbedtls_asn1_get_len( p, end, &len ) ) != 0 )
278|            return( ret );
279|
280|        if( ( tag & tag_may_mask ) == tag_may_val )
281|        {
282|            if( cb != NULL )
283|            {
284|                ret = cb( ctx, tag, *p, len );
285|                if( ret != 0 )
286|                    return( ret );
287|            }
288|        }
289|
290|        *p += len;
291|    }
292|
293|    return( 0 );
294|}

625|static int x509_get_subject_alt_name( unsigned char **p,
626|                                      const unsigned char *end,
627|                                      mbedtls_x509_sequence *subject_alt_name )
628|{
629|    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
630|    size_t len, tag_len;
631|    mbedtls_asn1_buf *buf;
632|    unsigned char tag;
633|    mbedtls_asn1_sequence *cur = subject_alt_name;
634|
635|    /* Get main sequence tag */
636|    if( ( ret = mbedtls_asn1_get_tag( p, end, &len,
637|            MBEDTLS_ASN1_CONSTRUCTED | MBEDTLS_ASN1_SEQUENCE ) ) != 0 )
638|        return( MBEDTLS_ERROR_ADD( MBEDTLS_ERR_X509_INVALID_EXTENSIONS, ret ) );
639|
640|    if( *p + len != end )
641|        return( MBEDTLS_ERROR_ADD( MBEDTLS_ERR_X509_INVALID_EXTENSIONS,
642|                MBEDTLS_ERR_ASN1_LENGTH_MISMATCH ) );
643|
644|    while( *p < end )
645|    {
646|        mbedtls_x509_subject_alternative_name dummy_san_buf;
647|        memset( &dummy_san_buf, 0, sizeof( dummy_san_buf ) );
648|
649|        tag = **p;
650|        (*p)++;
651|        if( ( ret = mbedtls_asn1_get_len( p, end, &tag_len ) ) != 0 )
652|            return( MBEDTLS_ERROR_ADD( MBEDTLS_ERR_X509_INVALID_EXTENSIONS, ret ) );
653|
654|        if( ( tag & MBEDTLS_ASN1_TAG_CLASS_MASK ) !=
655|                MBEDTLS_ASN1_CONTEXT_SPECIFIC )
656|        {
657|            return( MBEDTLS_ERROR_ADD( MBEDTLS_ERR_X509_INVALID_EXTENSIONS,
658|                    MBEDTLS_ERR_ASN1_UNEXPECTED_TAG ) );
659|        }
660|
661|        /*
662|         * Check that the SAN is structured correctly.
663|         */
664|        ret = mbedtls_x509_parse_subject_alt_name( &(cur->buf), &dummy_san_buf );
665|        /*
666|         * In case the extension is malformed, return an error,
667|         * and clear the allocated sequences.
668|         */
669|        if( ret != 0 && ret != MBEDTLS_ERR_X509_FEATURE_UNAVAILABLE )
670|        {
671|            mbedtls_x509_sequence *seq_cur = subject_alt_name->next;
672|            mbedtls_x509_sequence *seq_prv;
673|            while( seq_cur != NULL )
674|            {
675|                seq_prv = seq_cur;
676|                seq_cur = seq_cur->next;
677|                mbedtls_platform_zeroize( seq_prv,
678|                                          sizeof( mbedtls_x509_sequence ) );
679|                mbedtls_free( seq_prv );
680|            }
681|            subject_alt_name->next = NULL;
682|            return( ret );
683|        }
684|
685|        /* Allocate and assign next pointer */
686|        if( cur->buf.p != NULL )
687|        {
688|            if( cur->next != NULL )
689|                return( MBEDTLS_ERR_X509_INVALID_EXTENSIONS );
690|
691|            cur->next = mbedtls_calloc( 1, sizeof( mbedtls_asn1_sequence ) );
692|
693|            if( cur->next == NULL )
694|                return( MBEDTLS_ERROR_ADD( MBEDTLS_ERR_X509_INVALID_EXTENSIONS,
695|                        MBEDTLS_ERR_ASN1_ALLOC_FAILED ) );
696|
697|            cur = cur->next;
698|        }
699|
700|        buf = &(cur->buf);
701|        buf->tag = tag;
702|        buf->p = *p;
703|        buf->len = tag_len;
704|        *p += buf->len;
705|    }
706|
707|    /* Set final sequence entry's next pointer to NULL */
708|    cur->next = NULL;
709|
710|    if( *p != end )
711|        return( MBEDTLS_ERROR_ADD( MBEDTLS_ERR_X509_INVALID_EXTENSIONS,
712|                MBEDTLS_ERR_ASN1_LENGTH_MISMATCH ) );
713|
714|    return( 0 );
715|}

