787|     */
788|    if( len == 0 )
789|        return( MBEDTLS_ERROR_ADD( MBEDTLS_ERR_X509_INVALID_EXTENSIONS,
790|                MBEDTLS_ERR_ASN1_LENGTH_MISMATCH ) );
791|
792|    while( *p < end )
793|    {
794|        mbedtls_x509_buf policy_oid;
795|        const unsigned char *policy_end;
796|
797|        /*
798|         * Get the policy sequence
799|         */
800|        if( ( ret = mbedtls_asn1_get_tag( p, end, &len,
801|                MBEDTLS_ASN1_CONSTRUCTED | MBEDTLS_ASN1_SEQUENCE ) ) != 0 )
802|            return( MBEDTLS_ERROR_ADD( MBEDTLS_ERR_X509_INVALID_EXTENSIONS, ret ) );
803|
804|        policy_end = *p + len;
805|
806|        if( ( ret = mbedtls_asn1_get_tag( p, policy_end, &len,
807|                                          MBEDTLS_ASN1_OID ) ) != 0 )
808|            return( MBEDTLS_ERROR_ADD( MBEDTLS_ERR_X509_INVALID_EXTENSIONS, ret ) );
809|
810|        policy_oid.tag = MBEDTLS_ASN1_OID;
811|        policy_oid.len = len;
812|        policy_oid.p = *p;
813|
814|        /*
815|         * Only AnyPolicy is currently supported when enforcing policy.
816|         */
817|        if( MBEDTLS_OID_CMP( MBEDTLS_OID_ANY_POLICY, &policy_oid ) != 0 )
818|        {
819|            /*
820|             * Set the parsing return code but continue parsing, in case this
821|             * extension is critical.
822|             */
823|            parse_ret = MBEDTLS_ERR_X509_FEATURE_UNAVAILABLE;
824|        }
825|
826|        /* Allocate and assign next pointer */
827|        if( cur->buf.p != NULL )
828|        {
829|            if( cur->next != NULL )
830|                return( MBEDTLS_ERR_X509_INVALID_EXTENSIONS );
831|
832|            cur->next = mbedtls_calloc( 1, sizeof( mbedtls_asn1_sequence ) );
833|
834|            if( cur->next == NULL )
835|                return( MBEDTLS_ERROR_ADD( MBEDTLS_ERR_X509_INVALID_EXTENSIONS,
836|                        MBEDTLS_ERR_ASN1_ALLOC_FAILED ) );
837|
838|            cur = cur->next;
839|        }
840|
841|        buf = &( cur->buf );
842|        buf->tag = policy_oid.tag;
843|        buf->p = policy_oid.p;
844|        buf->len = policy_oid.len;
845|
846|        *p += len;
847|
848|       /*
849|        * If there is an optional qualifier, then *p < policy_end
850|        * Check the Qualifier len to verify it doesn't exceed policy_end.
851|        */
852|        if( *p < policy_end )
853|        {
854|            if( ( ret = mbedtls_asn1_get_tag( p, policy_end, &len,
855|                     MBEDTLS_ASN1_CONSTRUCTED | MBEDTLS_ASN1_SEQUENCE ) ) != 0 )
856|                return( MBEDTLS_ERROR_ADD( MBEDTLS_ERR_X509_INVALID_EXTENSIONS, ret ) );
857|            /*
858|             * Skip the optional policy qualifiers.
859|             */
860|            *p += len;
861|        }
862|
863|        if( *p != policy_end )
864|            return( MBEDTLS_ERROR_ADD( MBEDTLS_ERR_X509_INVALID_EXTENSIONS,
865|                    MBEDTLS_ERR_ASN1_LENGTH_MISMATCH ) );
866|    }
867|
868|    /* Set final sequence entry's next pointer to NULL */
869|    cur->next = NULL;
870|
871|    if( *p != end )
872|        return( MBEDTLS_ERROR_ADD( MBEDTLS_ERR_X509_INVALID_EXTENSIONS,
873|                MBEDTLS_ERR_ASN1_LENGTH_MISMATCH ) );
874|
875|    return( parse_ret );
876|}

